const body = $input.first().json.body || $input.first().json;
const required = ['idempotency_key', 'delivery_intent_key', 'channel', 'recipient', 'callback_url'];
const missing = required.filter((field) => !body[field]);
const channel = String(body.channel || '').toUpperCase();
if (channel === 'EMAIL' && !body.qr_base64_png) {
  missing.push('qr_base64_png');
}
return [{
  json: {
    valid: missing.length === 0,
    missingFields: missing,
    body: { ...body, channel },
  },
}];

const item = $input.first().json;
const buffer = Buffer.from(item.body.qr_base64_png, 'base64');
return [{
  json: item,
  binary: {
    qr: {
      data: buffer.toString('base64'),
      mimeType: 'image/png',
      fileName: 'qr-code.png',
    },
  },
}];

